function calcularTarifa(peso, destino, esSocio) {
  if (peso > 30) return null;
  let pen;
  if (peso <= 2) pen = 3.95;
  else if (peso <= 10) pen = 5.90;
  else pen = 5.90 + 0.45 * (peso - 10);
  let t;
  switch (destino) {
    case 'peninsula': t = pen; break;
    case 'baleares':
    case 'canarias': t = pen * 1.8; break;
    default: return null;
  }
  if (esSocio) t = t * 0.85;
  return t;
}

